$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ClosureResults";$case='ordinary_actual_endpoints';$exe="$root\Build\Release\m78-closure-$case.exe"
function Upload($p,$n){for($attempt=0;$attempt -lt 10;$attempt++){try{Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null;return}catch{if($attempt -eq 9){throw};Start-Sleep -Milliseconds 200}}}
try{
if(Test-Path $exe){throw 'Preserve previous witness executable'};Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-mixed_endpoint_v2-build.json" -OutFile "$out\ordinary-endpoint-link-receipt.json";$build=[IO.File]::ReadAllText("$out\ordinary-endpoint-link-receipt.json")|ConvertFrom-Json;Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-mixed_endpoint_v2-m78-closure-mixed_endpoint_v2.exe.bin" -OutFile $exe;if((Get-Item $exe).Length -ne $build.executableBytes -or (Get-FileHash $exe).Hash.ToLower() -ne $build.executableSHA256){throw 'Final actual-body witness identity changed'}
$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:JUDAS_DIAGNOSTIC_CONTINUE_WRITE=$null;$env:TEMP="$out\temp";$env:TMP=$env:TEMP;$env:APPDATA="$out\userdata\Roaming";$env:LOCALAPPDATA="$out\userdata\Local";$runs=@()
foreach($kind in @('stand','recovery')){$source="$out\balance-cold-$kind";$dest="$out\ordinary-actual-$kind";if(Test-Path $dest){throw 'Preserve previous ordinary actual capture'};New-Item -ItemType Directory $dest|Out-Null;Copy-Item "$source\project","$source\slots" $dest -Recurse;$snapshot=(Get-FileHash "$source\slots\m77.save").Hash.ToLower();if((Get-FileHash "$dest\slots\m77.save").Hash.ToLower() -ne $snapshot){throw 'Original new-format snapshot copy changed'};$mode="cold-$kind-read";$name="m78-closure-ordinary-actual-$kind";$w=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process $exe -WorkingDirectory "$root\Source" -ArgumentList @($dest,$mode) -PassThru -RedirectStandardOutput "$out\$name.stdout.log" -RedirectStandardError "$out\$name.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;throw 'Only owned actual endpoint timeout'};$p.Refresh();$exit=$p.ExitCode;$p.Dispose();$w.Stop();$files=@();foreach($f in @(Get-ChildItem $dest -File|Where-Object {$_.Extension -in '.json','.jsonl'})+@(Get-ChildItem "$dest\slots" -File)){$report="$name-$($f.Name)";Upload $f.FullName $report;$files+=@{path=$f.FullName;reportName=$report;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLower()}};$endpoint=[IO.File]::ReadAllText("$dest\physical-final.json")|ConvertFrom-Json;if(!$endpoint.currentPhysicalEndpoint.currentPhysicalStanding){throw 'Actual physical endpoint does not satisfy original standing contract'};$run=@{run=$name;exitCode=$exit;expectedExitCode=0;seconds=$w.Elapsed.TotalSeconds;originalSnapshotSHA256=$snapshot;executableSHA256=$build.executableSHA256;arguments=@($dest,$mode);files=$files;actualCurrentPhysicalStanding=$endpoint.currentPhysicalEndpoint.currentPhysicalStanding};$runs+=$run;$rp="$out\$name.json";$run|ConvertTo-Json -Depth 6|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp));Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";if($exit -ne 0){throw 'Actual endpoint test failed'}}
$rp="$out\m78-closure-$case-build.json";@{scope='Exact already-linked mixed physical observer reused for ordinary fresh M77 standing/recovery snapshots; read mode does not insert the independent motor. Original snapshots copied byte-exact to NEW output namespaces. Actual bodies and current contacts derive endpoint independently of cached Observation.';case=$case;archive=$build.archive;replacementObjects=$build.replacementObjects;reusedExecutableSHA256=$build.executableSHA256;executable=$exe;executableBytes=$build.executableBytes;runs=$runs;generatedFiles=@(@{path=$exe;name=[IO.Path]::GetFileName($exe);bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe).Hash.ToLower()});ownedLargeEvidence=@();freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 8|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp));Upload $exe ('m78-closure-'+$case+'-'+[IO.Path]::GetFileName($exe)+'.bin')
}catch{$_|Out-String|Set-Content "$out\m78-closure-$case-error.txt";Upload "$out\m78-closure-$case-error.txt" "m78-closure-$case-error.txt";exit 1}
